DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT114-S1-Q4$batch13$ AND q.stimulus=$batch13$An anthropologist hypothesized that a certain medicinal powder contained a significant amount of the deadly toxin T. When the test she performed for the presence of toxin T was negative, the anthropologist did not report the results. A chemist who nevertheless learned about the test results charged the anthropologist with fraud. The anthropologist, however, countered that those results were invalid because the powder had inadvertently been tested in an acidic solution.$batch13$ AND q.prompt=$batch13$Which one of the following, if true, most strengthens the anthropologist's counterargument?$batch13$ AND q.correct_choice=$batch13$C$batch13$) THEN RAISE EXCEPTION 'Question changed: PT114-S1-Q4'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch13$PT114-S1-Q4$batch13$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT114-S1-Q4'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT114-S1-Q4$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
